import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let ABCD be an axis-aligned rectangle with side lengths {width} and {height}, where the diagonal length sqrt(width^2 + height^2) is an integer. A circle of radius {radius} is placed uniformly at random so that it lies entirely within the rectangle (equivalently, the center is chosen uniformly from all points whose distance to each side is at least {radius}). What is m + n if the probability that the circle does not touch either diagonal AC or BD equals m/n in lowest terms?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose legs from a Pythagorean triple so that sqrt(width^2 + height^2) is integer
triples = [
    (3,4,5), (5,12,13), (8,15,17), (7,24,25), (9,40,41),
    (12,35,37), (20,21,29), (28,45,53), (11,60,61), (16,63,65), (33,56,65)
]
for _ in range(1000):
    a,b,c = rng.choice(triples)
    k = rng.randint(1, 3)
    A, B, C = k*a, k*b, k*c  # legs and hypotenuse
    # Make width >= height
    w, h = (A, B) if A >= B else (B, A)
    sqrtD = C
    D = sqrtD*sqrtD
    # Compute strict bounds ensuring the two-strip intersection fits entirely in the allowed region
    # 1) Ensure 2r < N where N is the d-extent in AC coordinates: r < WH / (W + H + sqrtD)
    # Use strict integer bound: r <= floor((WH - 1) / (W + H + sqrtD))
    WH = w*h
    denom1 = w + h + sqrtD
    r_max1 = (WH - 1) // denom1
    # 2) Ensure 2r/sin(phi) < S (no clipping in s), where sin(phi) = 2WH/D
    # Derived strict bound: r < D*WH / (D*sqrtD + 2WH(W+H))
    num2 = D * WH - 1
    den2 = D * sqrtD + 2 * WH * (w + h)
    r_max2 = num2 // den2
    # 3) Ensure positive available area: W - 2r > 0 and H - 2r > 0
    r_max3 = (min(w, h) - 1) // 2
    r_max = min(r_max1, r_max2, r_max3)
    if r_max >= 1:
        r = rng.randint(1, r_max)
        return {
            'width': w,
            'height': h,
            'radius': r
        }
# Fallback (should not happen): pick a safe default
return {'width': 36, 'height': 15, 'radius': 3}

    def verifier(assign):
from fractions import Fraction
import math
if not all(k in assign for k in ('width','height','radius')):
    return (False, None)  # Missing slots
w = int(assign['width']); h = int(assign['height']); r = int(assign['radius'])
if w <= 0 or h <= 0 or r <= 0:
    return (False, None)  # Invalid dimensions
# Ensure w >= h
if w < h:
    return (False, None)
# Check hypotenuse is integer
D = w*w + h*h
sqrtD = math.isqrt(D)
if sqrtD*sqrtD != D:
    return (False, None)  # Not a Pythagorean pair
# Available area must be positive
if w - 2*r <= 0 or h - 2*r <= 0:
    return (False, None)
# Compute S, N, and sin(phi)
# S is the s-extent of the inset rectangle in AC-aligned coords
S = Fraction(D - 2*r*(w + h), sqrtD)  # >= 0 if valid
# N is the d-extent; in our setup N = 2*(WH - r(W+H))/sqrtD
WH = w*h
N = Fraction(2*(WH - r*(w + h)), sqrtD)
# sin(phi) between diagonals AC and BD
sin_phi = Fraction(2*WH, D)
# Enforce difficulty and nontrivial regime: strict inequalities to avoid clipping/saturation
# 2r < N and 2r/sin(phi) < S
if not (Fraction(2*r,1) < N):
    return (False, None)
if not (Fraction(2*r,1) / sin_phi < S):
    return (False, None)
area_total = (w - 2*r) * (h - 2*r)
if area_total <= 0:
    return (False, None)
# Area that causes touching either diagonal = sum of two bands minus their intersection
# Each band area = 2r * S (since 2r < N guaranteed). Both diagonals have same S by symmetry.
band_area_each = Fraction(2*r,1) * S
intersection_area = Fraction(4*r*r,1) / sin_phi  # area of intersection of the two width-2r strips
union_area = 2*band_area_each*2 - intersection_area  # = 4r S - 4 r^2 / sin_phi
# Sanity bounds
if union_area <= 0:
    return (False, None)
if union_area > area_total:
    return (False, None)
# Probability not touching either diagonal
p_not = Fraction(area_total,1) - union_area
p_not /= area_total
# Ensure nontrivial probability
if not (Fraction(0,1) < p_not < Fraction(1,1)):
    return (False, None)
# Reduced fraction m/n
m = p_not.numerator
n = p_not.denominator
answer = m + n
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

